  Lemma scratch_lo : forall LF m1 XS, as_RFS H LF m1 -> Forall (fs_scratch H LF) XS -> Forall (fun iv : Z * Z => AIMG_TOP <= fst iv) XS.
  Proof. intros LF m1 XS RF FX. eapply Forall_impl; [| exact FX]. intros iv K. exact (proj1 (proj2 (scratch_facts H HH LF m1 [] iv RF K))). Qed.

  Lemma not_rin_lo : forall X a, Forall (fun iv : Z * Z => AIMG_TOP <= fst iv) X -> a < AIMG_TOP -> ~ rin_ivs X a.
  Proof. intros X a FX Ha. apply not_rin_of_Forall. eapply Forall_impl; [| exact FX]. intros [l h] K. cbn [fst snd] in *. left. lia. Qed.

  Lemma HS_xpres_lo : forall LB SP X m m', HS m -> xpres H LB SP X m m' -> Forall (fun iv : Z * Z => AIMG_TOP <= fst iv) X -> HS m'.
  Proof.
    intros LB SP X m m' K XP FX. eapply HSL; [exact K|]. intros a Ha. unfold AXH_LO, AXH_HI in Ha.
    refine (proj1 (XP a ltac:(clear - Ha; lia) _)). split; [right; left; unfold aimg_client; clear - Ha; lia|].
    apply (not_rin_lo _ _ FX). unfold AIMG_TOP. clear - Ha. lia.
  Qed.
  Lemma AXImg_xpres_lo : forall LB SP X m m', AXImg m -> xpres H LB SP X m m' -> Forall (fun iv : Z * Z => AIMG_TOP <= fst iv) X -> AXImg m'.
  Proof.
    intros LB SP X m m' K XP FX. eapply AXImg_agree; [exact K|]. intros a Ha. unfold AXRELRO_LO, AXRELRO_HI, AXDATA_LO, AXDATA_HI in Ha.
    refine (proj1 (XP a ltac:(clear - Ha; lia) _)). split; [right; left; unfold aimg_client; clear - Ha; lia|].
    apply (not_rin_lo _ _ FX). unfold AIMG_TOP. clear - Ha. lia.
  Qed.
  Lemma acanary_xpres_lo : forall LB SP X m m', acanary m -> xpres H LB SP X m m' -> Forall (fun iv : Z * Z => AIMG_TOP <= fst iv) X -> acanary m'.
  Proof.
    intros LB SP X m m' [can C] XP FX. exists can. eapply (xpres_rw_cells H); [exact XP| exact C|]. cbn [cells_size csize Nat.add].
    split; [right; left; intros a Ha; unfold aimg_client, A_STKCHK_GUARD in *; clear - Ha; lia|].
    eapply Forall_impl; [| exact FX]. intros [l h] K. cbn [fst snd] in *. left. unfold AIMG_TOP, A_STKCHK_GUARD in *. clear - K. lia.
  Qed.
  Lemma HS_munch_lo : forall W m m', HS m -> munch W m m' -> Forall (fun iv : Z * Z => AIMG_TOP <= fst iv) W -> HS m'.
  Proof.
    intros W m m' K MU FW. eapply HSL; [exact K|]. intros a Ha. unfold wa. apply MU. unfold AXH_LO, AXH_HI in Ha. rewrite unsigned_lit by (clear - Ha; lia).
    clear MU. induction W as [|[l h] W IH]; [exact I|]. cbn. pose proof (Forall_inv FW) as K1. cbn in K1. split; [unfold AIMG_TOP in K1; clear - Ha K1; lia| exact (IH (Forall_inv_tail FW))].
  Qed.
  Lemma AXImg_munch_lo : forall W m m', AXImg m -> munch W m m' -> Forall (fun iv : Z * Z => AIMG_TOP <= fst iv) W -> AXImg m'.
  Proof.
    intros W m m' K MU FW. eapply AXImg_agree; [exact K|]. intros a Ha. unfold wa. apply MU. unfold AXRELRO_LO, AXRELRO_HI, AXDATA_LO, AXDATA_HI in Ha.
    rewrite unsigned_lit by (clear - Ha; lia).
    clear MU. induction W as [|[l h] W IH]; [exact I|]. cbn. pose proof (Forall_inv FW) as K1. cbn in K1. split; [unfold AIMG_TOP in K1; clear - Ha K1; lia| exact (IH (Forall_inv_tail FW))].
  Qed.
  Lemma acanary_munch_lo : forall W m m', acanary m -> munch W m m' -> wmono bsegs m m' -> Forall (fun iv : Z * Z => AIMG_TOP <= fst iv) W -> acanary m'.
  Proof.
    intros W m m' K MU WM FW. eapply acanary_munch_keep; [exact K| exact MU| exact WM|]. apply disjoint_from_Forall.
    eapply Forall_impl; [| exact FW]. intros [l h] K1. cbn [fst snd] in *. left. unfold A_STKCHK_GUARD, AIMG_TOP in *. clear - K1. lia.
  Qed.

  Lemma HS_xpres_X : forall LB SP X m m', HS m -> xpres H LB SP X m m' -> Forall (fun iv : Z * Z => AXH_HI <= fst iv \/ snd iv <= AXH_LO) X -> HS m'.
  Proof.
    intros LB SP X m m' K XP FX. eapply HSL; [exact K|]. intros a Ha.
    refine (proj1 (XP a ltac:(unfold AXH_LO, AXH_HI in Ha; clear - Ha; lia) _)). split; [right; left; unfold aimg_client, AXH_LO, AXH_HI in *; clear - Ha; lia|].
    apply not_rin_of_Forall. eapply Forall_impl; [| exact FX]. intros [l h] Q. cbn [fst snd] in *. clear - Ha Q. lia.
  Qed.
  Lemma AXImg_xpres_X : forall LB SP X m m', AXImg m -> xpres H LB SP X m m' ->
    Forall (fun iv : Z * Z => AXDATA_HI <= fst iv \/ snd iv <= AXRELRO_LO) X -> AXImg m'.
  Proof.
    intros LB SP X m m' K XP FX. eapply AXImg_agree; [exact K|]. intros a Ha.
    refine (proj1 (XP a ltac:(unfold AXRELRO_LO, AXRELRO_HI, AXDATA_LO, AXDATA_HI in Ha; clear - Ha; lia) _)).
    split; [right; left; unfold aimg_client, AXRELRO_LO, AXRELRO_HI, AXDATA_LO, AXDATA_HI in *; clear - Ha; lia|].
    apply not_rin_of_Forall. eapply Forall_impl; [| exact FX]. intros [l h] Q. cbn [fst snd] in *. unfold AXRELRO_LO, AXRELRO_HI, AXDATA_LO, AXDATA_HI in *. clear - Ha Q. lia.
  Qed.

